HTML = "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Event programmes · Analysis</title><link rel=\"stylesheet\" href=\"/event-programmes.css\"><script src=\"/event-programmes.js\" defer></script></head>\n<body><header><div><p class=\"eyebrow\">STELLAR FORGE / CUSTOMER ANALYSIS</p><h1>Event programmes</h1></div><a id=\"workspace-link\" href=\"/\">Open Analysis workspace</a></header>\n<main><p id=\"message\" role=\"status\" aria-live=\"polite\">Connecting to the customer workspace.</p>\n<section><div class=\"heading\"><h2>Customer programme</h2><button id=\"refresh\">Refresh</button></div><p>Receive the original completed subscriber window, review its data and keep the customer's saved report and workbook through later windows.</p>\n<div class=\"row\"><label>Existing programme<select id=\"programmes\"><option value=\"\">New programme</option></select></label><label>Programme name<input id=\"programme\" maxlength=\"24\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"customer_events\"></label><button id=\"open-programme\">Open programme</button></div><p id=\"programme-info\"></p><p id=\"receiver-info\"></p>\n<details><summary>Current programme and complete operation history</summary><pre id=\"programme-state\"></pre></details></section>\n<section><h2>Receive the original files</h2><p>Choose the complete NDJSON export and its original manifest. File identity and upload progress are retained in this workspace. Reselect the same files to continue a stopped upload.</p>\n<div class=\"row\"><label>Events NDJSON<input id=\"ndjson\" type=\"file\" accept=\".ndjson,.jsonl,application/x-ndjson\"></label><label>Original export manifest<input id=\"manifest\" type=\"file\" accept=\".json,application/json\"></label></div>\n<div class=\"row\"><button id=\"receive\">Receive complete files</button><button id=\"new-input\">Use another source pair</button></div><p id=\"input-status\"></p><progress id=\"upload-progress\" max=\"100\" value=\"0\" hidden></progress>\n<div class=\"row\"><label>Retained source pair<select id=\"inputs\"><option value=\"\">Select source files</option></select></label><button id=\"open-input\">Open source pair</button><button id=\"older-inputs\">Older source pairs</button><button id=\"latest-inputs\">Latest source pairs</button></div><pre id=\"input-metadata\"></pre></section>\n<section><h2>Choose useful payload fields</h2><p>Original identity, sequence, event type, timing and complete payload remain in the table. Add fields using JSON Pointer paths inside the payload. Exact values stay text; adjacent state columns identify missing, null and JSON kinds.</p>\n<details id=\"payload-explorer\"><summary>Explore the original payload fields</summary>\n<p>Scan every received event before choosing fields. Coverage describes this complete source window. Short examples are labelled previews; open values to read the complete original value and event identity.</p>\n<div class=\"row\"><button id=\"inspect-fields\">Inspect complete source</button><label>Find payload path or type<input id=\"field-query\" type=\"search\" placeholder=\"/amount, string, null\"></label><button id=\"download-fields\">Download complete field catalogue</button></div>\n<p id=\"catalogue-status\">Choose a complete retained source pair.</p>\n<div class=\"scroll-table\"><table><thead><tr><th>Payload pointer</th><th>Coverage</th><th>Original JSON kinds</th><th>Example preview</th><th></th></tr></thead><tbody id=\"field-catalogue\"></tbody></table></div>\n<div class=\"row\"><button id=\"fields-before\">Previous paths</button><button id=\"fields-after\">Next paths</button></div>\n<section id=\"field-values\" hidden><h3 id=\"field-values-title\">Original field values</h3><p id=\"field-values-state\"></p><div id=\"field-values-rows\"></div><div class=\"row\"><button id=\"values-before\">Earlier events</button><button id=\"values-after\">Later events</button><button id=\"download-values\">Download these complete values</button></div></section>\n</details>\n<div class=\"row\"><button id=\"export-mapping\">Download complete mapping</button><label>Mapping for this original source<input id=\"mapping-file\" type=\"file\" accept=\".json,application/json\"></label><button id=\"import-mapping\">Open selected mapping</button></div>\n<table><thead><tr><th>Column name</th><th>Payload pointer</th><th></th></tr></thead><tbody id=\"fields\"></tbody></table>\n<div class=\"row\"><button id=\"add-field\">Add field</button><button id=\"use-accepted\">Use accepted field mapping</button><button id=\"review\">Review complete source window</button></div><p id=\"draft-info\"></p></section>\n<section><div class=\"heading\"><h2>Review and continue</h2><button id=\"resume\" hidden>Continue original saved action</button></div>\n<p id=\"action-state\"></p><div id=\"review-facts\" class=\"facts\"></div><details><summary>Complete selected review and native result</summary><pre id=\"review-state\"></pre></details>\n<label>Customer decision or reason for selecting current edits<textarea id=\"note\" rows=\"3\" maxlength=\"8000\"></textarea></label>\n<div id=\"column-choice\" hidden><h3>Retain worksheet choices</h3><p>The original workbook contains columns that need an explicit selection. Review its complete proposal, then provide the complete column arrays by worksheet index. Open Workbooks in Analysis for the customer's saved names, notes and conversions.</p><pre id=\"column-proposal\"></pre><label>Reviewed worksheet columns<textarea id=\"columns\" rows=\"8\" spellcheck=\"false\">{}</textarea></label></div>\n<div class=\"row\"><button id=\"apply\">Apply reviewed window</button><button id=\"refresh-review\">Review current customer edits</button><button id=\"deliver\">Prepare complete delivery</button></div><p>When customer work changes during an unfinished selected operation, review those current edits before continuing. The original attempt and decision remain in the programme history.</p>\n<div id=\"downloads\"></div></section>\n<section><h2>Saved actions</h2><p>Open an original action to read its full result or explicitly continue it after an interruption.</p><table><thead><tr><th>Programme</th><th>Action</th><th>Status</th><th>Saved</th><th></th></tr></thead><tbody id=\"actions\"></tbody></table>\n<div class=\"row\"><button id=\"older-actions\">Older actions</button><button id=\"latest-actions\">Latest actions</button></div></section>\n</main></body></html>\n"

CSS = ":root{color-scheme:light;font-family:system-ui,-apple-system,sans-serif;color:#242424;background:#fff;font-size:15px;line-height:1.5}*{box-sizing:border-box}body{margin:0}header,main{max-width:1180px;margin:auto;padding:24px 30px}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ccc;gap:20px}h1{font-size:26px;margin:4px 0}h2{font-size:19px;margin:0 0 12px}h3{font-size:16px}.eyebrow{font-size:11px;letter-spacing:.1em;margin:0}a{color:inherit;text-underline-offset:3px}section{border:1px solid #ccc;padding:22px;margin:20px 0}.row,.heading{display:flex;gap:14px;align-items:end;flex-wrap:wrap;margin:16px 0}.heading{justify-content:space-between;align-items:center}label{display:block;flex:1;min-width:180px;font-weight:600}input,select,textarea{display:block;width:100%;font:inherit;border:1px solid #888;border-radius:2px;padding:8px;margin-top:5px;background:white;color:inherit}button{font:inherit;color:inherit;background:#f4f4f4;border:1px solid #888;border-radius:2px;padding:8px 12px;cursor:pointer}button:disabled{opacity:.45;cursor:default}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid #111;outline-offset:3px}pre{font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:30rem;overflow:auto;background:#f6f6f6;padding:12px}table{width:100%;border-collapse:collapse}th,td{text-align:left;vertical-align:top;padding:9px;border-bottom:1px solid #ddd;overflow-wrap:anywhere}th{font-size:13px}#message{padding:12px;border-left:3px solid #555;background:#f5f5f5;overflow-wrap:anywhere}#message[data-error=true]{border-left-width:6px;font-weight:600}.facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;overflow-wrap:anywhere}.facts strong{display:block;font-size:12px}progress{width:100%}[hidden]{display:none!important}#downloads button{margin:5px}#fields input{min-width:100px}@media(max-width:640px){header,main{padding:18px 14px}section{padding:16px}header{align-items:start}th,td{padding:6px}.row{display:block}.row>*{margin-top:10px}}\n\n.scroll-table{overflow:auto}.scroll-table th:first-child{min-width:180px}.scroll-table th:last-child{min-width:140px}.payload-value{border-top:1px solid #ddd;padding:12px 0}.payload-value p{overflow-wrap:anywhere}.payload-value pre{max-height:24rem}#payload-explorer{margin:18px 0}#payload-explorer summary{font-weight:600;cursor:pointer}#field-values{border:0;border-top:1px solid #bbb;padding:16px 0}#field-values-rows{max-height:45rem;overflow:auto}"

JS = "'use strict';\n(()=>{\nconst $=id=>document.getElementById(id), node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};\nconst capability=location.hash.slice(1);history.replaceState(null,'',location.pathname);\n$('workspace-link').href='/#'+capability;\nconst root='/api/event-programmes';\nconst state={workspace:null,overview:null,programme:null,input:null,action:null,review:null,operation:null,fields:[],busy:false,generation:0,actionsBefore:null,inputsBefore:null,poll:null,catalogue:null,fieldPage:0,fieldValues:null};\nconst uuid=()=>crypto.randomUUID().replaceAll('-','');\nconst hex=buffer=>Array.from(new Uint8Array(buffer),v=>v.toString(16).padStart(2,'0')).join('');\nconst hash=async data=>hex(await crypto.subtle.digest('SHA-256',data));\nconst sameFiles=(left,right)=>['ndjson','manifest'].every(kind=>left?.[kind]&&right?.[kind]&&['name','bytes','sha256'].every(key=>left[kind][key]===right[kind][key]));\nconst base64=buffer=>{let text='';for(const byte of new Uint8Array(buffer))text+=String.fromCharCode(byte);return btoa(text);};\nfunction message(text,error=false){$('message').textContent=text;$('message').dataset.error=String(error);}\nasync function api(path,body){\n const result=await fetch(path,{method:body===undefined?'GET':'POST',cache:'no-store',headers:{'X-Analysis-Capability':capability,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body)});\n const data=await result.json();if(!result.ok)throw Error(data.error||'The original request could not be completed.');return data;\n}\nfunction selectedName(){const value=$('programme').value.trim();if(!/^[A-Za-z][A-Za-z0-9_]{0,23}$/.test(value))throw Error('Choose a programme name beginning with a letter, at most 24 letters, digits or underscores.');return value;}\nfunction controls(){\n const unavailable=state.busy||!state.workspace, running=state.action?.status==='RUNNING'||!!state.overview?.active;\n for(const e of document.querySelectorAll('button,input,select,textarea'))e.disabled=unavailable;\n for(const id of ['review','apply','refresh-review','deliver','receive','new-input'])$(id).disabled||=running;\n $('review').disabled||=!state.input?.complete;\n $('inspect-fields').disabled||=!state.input?.complete||running;\n $('download-fields').disabled||=!state.catalogue;\n $('export-mapping').disabled||=!state.catalogue;\n $('import-mapping').disabled||=!state.catalogue;\n $('fields-before').disabled||=!state.catalogue||state.fieldPage===0;\n $('fields-after').disabled||=!state.catalogue||(state.fieldPage+1)*50>=catalogueRows().length;\n $('values-before').disabled||=!state.fieldValues||state.fieldValues.offset===0;\n $('values-after').disabled||=!state.fieldValues||state.fieldValues.next_offset===null;\n $('download-values').disabled||=!state.fieldValues;\n for(const control of document.querySelectorAll('[data-field-selectable]'))control.disabled||=control.dataset.fieldSelectable!=='true';\n $('apply').disabled||=!state.review||!!state.programme?.operations.find(x=>x.id===state.operation)?.applied;\n $('refresh-review').disabled||=!state.review||state.programme?.programme.pending!==state.operation;\n $('deliver').disabled||=!state.operation||!state.programme?.operations.find(x=>x.id===state.operation)?.applied;\n $('resume').hidden=!state.action||!['ERROR','INTERRUPTED','READY'].includes(state.action.status);\n $('resume').disabled||=running;\n $('use-accepted').disabled||=!state.programme?.programme.accepted;\n $('older-actions').disabled||=!state.overview?.next_actions;\n $('older-inputs').disabled||=!state.overview?.next_inputs;\n}\nasync function act(fn){if(state.busy)return;state.busy=true;controls();try{await fn();}catch(error){message(error.message,true);}finally{state.busy=false;controls();}}\nfunction draftKey(){return 'sf-event-fields:'+state.workspace+':'+$('programme').value;}\nfunction remember(){if(!state.workspace)return;try{localStorage.setItem(draftKey(),JSON.stringify({fields:state.fields,note:$('note').value,columns:$('columns').value}));$('draft-info').textContent='Field draft retained in this browser; complete reviewed selections live in the workspace.';}catch{$('draft-info').textContent='Browser draft storage is unavailable. Complete reviewed selections remain in the workspace.';}}\nfunction fieldRows(){\n $('fields').replaceChildren();\n state.fields.forEach((field,index)=>{\n  const row=node('tr'),a=node('td'),b=node('td'),c=node('td'),name=node('input'),pointer=node('input'),remove=node('button','Remove');\n  name.value=field.name;pointer.value=field.pointer;name.spellcheck=pointer.spellcheck=false;\n  name.setAttribute('aria-label','Column name '+(index+1));pointer.setAttribute('aria-label','Payload pointer '+(index+1));\n  name.addEventListener('input',()=>{field.name=name.value;remember();});pointer.addEventListener('input',()=>{field.pointer=pointer.value;remember();});\n  remove.addEventListener('click',()=>{state.fields.splice(index,1);fieldRows();remember();});\n  a.append(name);b.append(pointer);c.append(remove);row.append(a,b,c);$('fields').append(row);\n });controls();\n}\n\nfunction clearCatalogue(){\n state.catalogue=null;state.fieldPage=0;state.fieldValues=null;\n $('field-catalogue').replaceChildren();$('field-values').hidden=true;\n $('catalogue-status').textContent='Inspect the selected complete source pair to see its actual payload fields.';\n}\nfunction catalogueRows(){\n const query=$('field-query').value.toLowerCase().trim();\n return (state.catalogue?.fields||[]).filter(row=>!query||row.pointer.toLowerCase().includes(query)||\n  Object.entries(row.types).some(([kind,count])=>count>0&&kind.includes(query)));\n}\nfunction jsonDownload(value,name){\n const body=JSON.stringify(value,null,2)+'\\n',blob=new Blob([body],{type:'application/json'});\n const url=URL.createObjectURL(blob),link=node('a');link.href=url;link.download=name;\n document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);\n}\nfunction sourceIdentity(){\n if(!state.catalogue||state.catalogue.input_id!==state.input?.id)throw Error('Inspect the current complete source pair first.');\n return {workspace_id:state.catalogue.workspace_id,input_id:state.catalogue.input_id,\n  edition_id:state.catalogue.edition_id,source:state.catalogue.source,original_files:state.catalogue.original_files};\n}\nfunction validateInspection(value,schema,inputId){\n if(!value||value.schema!==schema||value.workspace_id!==state.workspace||value.input_id!==inputId||\n  !/^[a-f0-9]{64}$/.test(value.edition_id||'')||!Number.isSafeInteger(value.events)||value.events<0||\n  !['ndjson','manifest'].every(kind=>value.original_files?.[kind]?.bytes===state.input?.files[kind].bytes&&\n   value.original_files[kind].sha256===state.input.files[kind].sha256))\n  throw Error('The field inspection differs from the selected complete original source.');\n return value;\n}\nasync function inspectFields(){\n const id=state.input.id;\n const value=await api(root+'/inputs/'+id+'/fields');\n if(state.input?.id!==id)throw Error('The selected source pair changed. Reopen its field catalogue.');\n validateInspection(value,'stellar-forge.event-feed-payload-fields.v1',id);\n if(!Array.isArray(value.fields)||value.field_count!==value.fields.length)throw Error('Receive the complete field catalogue.');\n state.catalogue=value;state.fieldPage=0;state.fieldValues=null;$('field-values').hidden=true;\n renderCatalogue();message('Every actual payload path in '+value.events+' original events is available. Choose fields, inspect complete values, then review the useful mapping.');\n}\nfunction suggestField(path){\n const last=path===''?'payload':path.split('/').at(-1).replace(/~1/g,'/').replace(/~0/g,'~');\n let base=last.replace(/[^A-Za-z0-9_]/g,'_');if(!/^[A-Za-z]/.test(base))base='field_'+base;\n base=(base||'field').slice(0,40);\n const reserved=new Set(['store_id','feed_id','feed_revision','source_id','event_id','sequence','event_type',\n 'received_at','occurred_at','occurred_at_state','source_body_sha256','payload_sha256','payload_json']);\n for(const field of state.fields){reserved.add(field.name.toLowerCase());reserved.add((field.name+'_state').toLowerCase());}\n let chosen=base,number=1;\n while(reserved.has(chosen.toLowerCase())||reserved.has((chosen+'_state').toLowerCase()))chosen=base+'_'+number++;\n return chosen;\n}\nfunction chooseField(row){\n if(!row.selectable)throw Error('This original path exceeds the native 2,000-character mapping allowance. Select its useful parent field.');\n if(state.fields.length>=100)throw Error('The existing mapping supports at most 100 selected fields.');\n if(state.fields.some(field=>field.pointer===row.pointer)){message('This original path is already in the editable mapping.');return;}\n state.fields.push({name:suggestField(row.pointer),pointer:row.pointer});fieldRows();remember();renderCatalogue();\n}\nfunction renderCatalogue(){\n const catalogue=state.catalogue,rows=catalogueRows(),start=state.fieldPage*50;\n $('field-catalogue').replaceChildren();\n if(!catalogue){controls();return;}\n $('catalogue-status').textContent=catalogue.events+' complete events · '+catalogue.field_count+' original paths · '+\n  rows.length+' matching paths'+(rows.length?' · showing '+(start+1)+'–'+Math.min(start+50,rows.length):'')+\n  '. Source '+catalogue.edition_id+'.';\n if(!catalogue.events)$('catalogue-status').textContent+=' This is a complete empty window; use an accepted mapping or explicit customer field selections.';\n for(const row of rows.slice(start,start+50)){\n  const tr=node('tr'),path=node('td',row.pointer===''?'(whole payload)':row.pointer),\n   counts=node('td',row.present+' present / '+row.missing+' missing'),\n   kinds=node('td',Object.entries(row.types).filter(([,count])=>count).map(([kind,count])=>kind+': '+count).join(', ')),\n   examples=node('td'),actions=node('td');\n  for(const example of row.examples||[])examples.append(node('p',example.state+': '+\n   (example.display===null?'null':example.display)+(example.truncated?' [preview]':'')));\n  const use=node('button',state.fields.some(field=>field.pointer===row.pointer)?'Selected':'Use field');\n  use.disabled=!row.selectable;use.dataset.fieldSelectable=String(row.selectable);\n  use.addEventListener('click',()=>act(()=>chooseField(row)));\n  const values=node('button','Open original values');values.disabled=!row.selectable;values.dataset.fieldSelectable=String(row.selectable);\n  values.addEventListener('click',()=>act(()=>openFieldValues(row.pointer,0)));\n  actions.append(use,values);tr.append(path,counts,kinds,examples,actions);$('field-catalogue').append(tr);\n }\n controls();\n}\nasync function openFieldValues(pointer,offset){\n const identity=sourceIdentity(),value=await api(root+'/inputs/'+identity.input_id+'/inspect',{pointer,offset,limit:25});\n validateInspection(value,'stellar-forge.event-feed-payload-values.v1',identity.input_id);\n if(value.edition_id!==identity.edition_id||value.pointer!==pointer||value.offset!==offset||\n  !Array.isArray(value.rows)||value.total!==state.catalogue.events)throw Error('The complete original value selection changed.');\n state.fieldValues=value;renderValues();\n}\nfunction renderValues(){\n const value=state.fieldValues;$('field-values').hidden=!value;$('field-values-rows').replaceChildren();if(!value)return;\n $('field-values-title').textContent='Original values: '+(value.pointer||'(whole payload)');\n $('field-values-state').textContent=value.total+' original events · '+(value.rows.length?'showing '+(value.offset+1)+'–'+(value.offset+value.rows.length):'empty window')+\n  '. Text below is the complete native value. Missing, null and JSON kinds remain separate.';\n for(const row of value.rows){\n  const box=node('div');box.className='payload-value';\n  box.append(node('p','Event '+row.event.source_id+' / '+row.event.event_id+' · sequence '+row.event.sequence+\n   ' · '+row.event.event_type+' · '+row.state));\n  if(row.text===null)box.append(node('p',row.state==='missing'?'This path is missing from this event.':'This path contains JSON null.'));\n  else box.append(node('pre',row.text),node('p',row.value_bytes+' UTF-8 bytes · SHA-256 '+row.value_sha256));\n  $('field-values-rows').append(box);\n }\n controls();\n}\nfunction mappingHandover(){\n const original=sourceIdentity();\n return {schema:'stellar-forge.event-field-mapping-handover.v1',original,\n  mapping:{schema:'stellar-forge.event-feed-analysis-mapping.v1',fields:state.fields.map(field=>({...field}))}};\n}\nasync function importMapping(){\n const file=$('mapping-file').files[0];if(!file||file.size>1024*1024)throw Error('Select a complete mapping JSON file up to 1 MiB.');\n const value=JSON.parse(await file.text()),actual=sourceIdentity(),selected=value.original;\n if(value.schema!=='stellar-forge.event-field-mapping-handover.v1'||!selected||\n  ['workspace_id','input_id','edition_id'].some(key=>selected[key]!==actual[key])||\n  !['ndjson','manifest'].every(kind=>selected.original_files?.[kind]?.bytes===actual.original_files[kind].bytes&&\n   selected.original_files[kind].sha256===actual.original_files[kind].sha256))\n  throw Error('This mapping belongs to another original input. Open its selected source pair, or retain the current accepted mapping for a later source window.');\n const fields=value.mapping?.fields;\n if(!Array.isArray(fields)||fields.length>100||fields.some(field=>!field||typeof field.name!=='string'||\n  typeof field.pointer!=='string'||field.name.length>48||field.pointer.length>2000))\n  throw Error('Select a complete native mapping of at most 100 named payload paths.');\n const prior=state.fields.map(field=>({...field}));\n state.fields=fields.map(field=>({name:field.name,pointer:field.pointer}));\n try{remember();fieldRows();renderCatalogue();message('Opened the complete mapping for this exact original source. Review the field meanings and native review before applying.');}\n catch(error){state.fields=prior;fieldRows();throw error;}\n}\n$('inspect-fields').addEventListener('click',()=>act(inspectFields));\n$('field-query').addEventListener('input',()=>{state.fieldPage=0;renderCatalogue();});\n$('fields-before').addEventListener('click',()=>{state.fieldPage--;renderCatalogue();});\n$('fields-after').addEventListener('click',()=>{state.fieldPage++;renderCatalogue();});\n$('download-fields').addEventListener('click',()=>act(()=>jsonDownload(state.catalogue,'event-payload-fields-'+state.catalogue.edition_id.slice(0,16)+'.json')));\n$('values-before').addEventListener('click',()=>act(()=>openFieldValues(state.fieldValues.pointer,Math.max(0,state.fieldValues.offset-25))));\n$('values-after').addEventListener('click',()=>act(()=>openFieldValues(state.fieldValues.pointer,state.fieldValues.next_offset)));\n$('download-values').addEventListener('click',()=>act(()=>jsonDownload(state.fieldValues,'event-field-values-'+state.fieldValues.offset+'.json')));\n$('export-mapping').addEventListener('click',()=>act(()=>jsonDownload(mappingHandover(),'event-field-mapping-'+state.catalogue.edition_id.slice(0,16)+'.json')));\n$('import-mapping').addEventListener('click',()=>act(importMapping));\n\nfunction facts(value){$('review-facts').replaceChildren();for(const [label,text] of Object.entries(value)){const e=node('div');e.append(node('strong',label),node('span',String(text??'')));$('review-facts').append(e);}}\nfunction clearSelectedAction(){clearTimeout(state.poll);state.action=null;state.review=null;state.operation=null;$('review-state').textContent='';$('action-state').textContent='';$('downloads').replaceChildren();$('column-choice').hidden=true;facts({});}\nasync function openProgramme(value){\n remember();const generation=++state.generation;clearSelectedAction();$('programme').value=value;\n const data=await api(root+'/named/'+encodeURIComponent(selectedName()));if(generation!==state.generation)return;\n state.programme=data;$('programme-state').textContent=JSON.stringify(data,null,2);\n const current=data.programme;$('programme-info').textContent=current.accepted?'Accepted '+current.accepted.manifest.events+' events through sequence '+current.accepted.manifest.throughSequence+' · programme revision '+current.revision:'New programme; the first reviewed window creates its original report and workbook.';\n let draft;try{draft=JSON.parse(localStorage.getItem(draftKey()));}catch{}\n state.fields=Array.isArray(draft?.fields)?draft.fields:current.accepted?.mapping.fields.map(x=>({...x}))||[];\n $('note').value=draft?.note||'';$('columns').value=draft?.columns||'{}';fieldRows();\n const last=data.operations.at(-1);if(last){state.operation=last.id;state.review=last.review;renderReview(last); }\n controls();\n}\nasync function refreshProgramme(){\n if(!state.programme)return;const programme=state.programme.programme.name,generation=state.generation;\n const data=await api(root+'/named/'+encodeURIComponent(programme));if(generation!==state.generation)return;\n state.programme=data;$('programme-state').textContent=JSON.stringify(data,null,2);\n const current=data.programme;$('programme-info').textContent=current.accepted?'Accepted '+current.accepted.manifest.events+' events through sequence '+current.accepted.manifest.throughSequence+' · programme revision '+current.revision:'Awaiting the first accepted complete window.';\n const operation=data.operations.find(x=>x.id===state.operation);if(operation){state.review=operation.review;renderReview(operation);}controls();\n}\nfunction renderReview(operation){\n const review=operation.review;if(review){facts({'Events':review.manifest.events,'Through sequence':review.manifest.throughSequence,'Original pages':review.manifest.pages.length,'Earlier events retained':review.window_comparison?.retained??0,'New events':review.window_comparison?.added??review.manifest.events,'Selected fields':review.mapping.fields.length});}\n $('review-state').textContent=JSON.stringify(operation,null,2);\n $('downloads').replaceChildren();\n if(operation.delivery){$('downloads').append(node('h3','Complete customer delivery'),node('p','Selected result '+operation.delivery.edition_id+'; archived programme '+operation.delivery.workspace_programme_edition_id+'.'));\n  for(const file of operation.delivery.files){const button=node('button',file.name+' · '+file.bytes+' bytes');button.addEventListener('click',()=>act(()=>download(operation.id,file)));$('downloads').append(button);}\n }\n}\nasync function download(operation,file){\n const response=await fetch(root+'/named/'+encodeURIComponent(state.programme.programme.name)+'/delivery/'+operation+'/'+encodeURIComponent(file.name),{headers:{'X-Analysis-Capability':capability},cache:'no-store'});\n if(!response.ok){const value=await response.json();throw Error(value.error||'Prepare the complete delivery in this workspace before downloading.');}\n const blob=await response.blob();\n if(blob.size!==file.bytes||await hash(await blob.arrayBuffer())!==file.sha256)throw Error('The downloaded file differs from the original complete delivery.');\n const url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download=file.name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);\n}\nfunction renderInput(value){\n if(state.input?.id!==value.id)clearCatalogue();\n state.input=value;$('input-status').textContent='NDJSON '+value.received.ndjson+'/'+value.files.ndjson.bytes+' bytes; manifest '+value.received.manifest+'/'+value.files.manifest.bytes+' bytes.'+(value.complete?' Complete file pair retained.':' Reselect the same original files to continue.');\n $('input-metadata').textContent=JSON.stringify(value,null,2);\n try{localStorage.setItem('sf-event-input:'+state.workspace,JSON.stringify({id:value.id,files:value.files}));}catch{}\n controls();\n}\nasync function refresh(){\n const generation=state.generation;\n const query=new URLSearchParams();if(state.actionsBefore)query.set('actions_before',state.actionsBefore);if(state.inputsBefore)query.set('inputs_before',state.inputsBefore);\n const value=await api(root+(query.size?'?'+query:''));\n if(generation!==state.generation)return;\n if(state.workspace&&state.workspace!==value.workspace_id)throw Error('The original customer workspace changed.');\n state.workspace=value.workspace_id;state.overview=value;\n $('receiver-info').textContent=value.source_receiver_available?'The original event source receiver is available.':'Configure the local launch with the original event source receiver before reviewing a new file pair. Saved customer work remains available.';\n const current=$('programme').value;$('programmes').replaceChildren();const none=node('option','New programme');none.value='';$('programmes').append(none);\n for(const programme of value.programmes){const option=node('option',programme.name);option.value=programme.name;$('programmes').append(option);}if(value.programmes.some(x=>x.name===current))$('programmes').value=current;\n $('inputs').replaceChildren();for(const input of value.inputs){const option=node('option',input.files.ndjson.name+' · '+input.created_at);option.value=input.id;$('inputs').append(option);}if(state.input&&value.inputs.some(x=>x.id===state.input.id))$('inputs').value=state.input.id;\n $('actions').replaceChildren();for(const action of value.actions){const row=node('tr');for(const v of [action.programme,action.request.action,action.status,action.updated_at||action.created_at])row.append(node('td',v));const td=node('td'),button=node('button','Open');button.addEventListener('click',()=>act(()=>openAction(action.id)));td.append(button);row.append(td);$('actions').append(row);}\n controls();\n}\nasync function upload(){\n const files={ndjson:$('ndjson').files[0],manifest:$('manifest').files[0]};\n if(!files.ndjson||!files.manifest)throw Error('Choose both complete original files.');\n const limits={ndjson:32*1024*1024,manifest:4*1024*1024},identity={};\n for(const [kind,file] of Object.entries(files)){if(file.size>limits[kind])throw Error('The original '+kind+' file exceeds its complete source allowance.');identity[kind]={name:file.name,bytes:file.size,sha256:await hash(await file.arrayBuffer())};}\n let retained=state.input;\n if(!retained){try{const remembered=JSON.parse(localStorage.getItem('sf-event-input:'+state.workspace));if(remembered&&sameFiles(remembered.files,identity))retained=remembered;}catch{}}\n if(retained&&!sameFiles(retained.files,identity))throw Error('These are different files. Use another source pair to preserve the selected original receiving operation.');\n const intent={id:retained?.id||uuid(),files:identity};\n try{localStorage.setItem('sf-event-input:'+state.workspace,JSON.stringify(intent));}catch{}\n let received=await api(root+'/inputs',intent);renderInput(received);\n $('upload-progress').hidden=false;\n for(const [kind,file] of Object.entries(files)){\n  let offset=received.received[kind];\n  while(offset<file.size){const chunk=await file.slice(offset,offset+received.chunk_bytes).arrayBuffer();\n   received=await api(root+'/inputs/'+intent.id+'/'+kind,{offset,sha256:await hash(chunk),base64:base64(chunk)});offset=received.received[kind];\n   $('upload-progress').value=Math.round(100*(received.received.ndjson+received.received.manifest)/Math.max(1,files.ndjson.size+files.manifest.size));renderInput(received);\n  }\n }\n await refresh();message('Both complete original files are retained. Choose useful fields and review the complete source window.');\n}\nasync function submit(action,extra={}){\n const programme=selectedName();if(state.programme?.programme.name!==programme)await openProgramme(programme);\n const request={id:uuid(),action,operation_id:action==='review'?uuid():state.operation,...extra};\n if(!request.operation_id)throw Error('Open the original reviewed operation first.');\n state.action={id:request.id,programme,request:Object.fromEntries(Object.entries(request).filter(([k])=>k!=='id')),status:'INTERRUPTED',error:'The original request is retained for explicit continuation.'};\n try{localStorage.setItem('sf-event-action:'+state.workspace,JSON.stringify(state.action));}catch{}\n showAction(state.action);\n const value=await api(root+'/named/'+encodeURIComponent(programme)+'/actions',request);\n state.action=value;state.operation=value.request.operation_id;showAction(value);await refresh();schedule();\n}\nfunction showAction(value){\n state.action=value;try{localStorage.setItem('sf-event-action:'+state.workspace,JSON.stringify(value));}catch{}$('action-state').textContent=value.request.action+' · '+value.status+' · '+value.id+(value.error?' · '+value.error:'');\n if(value.result?.schema==='stellar-forge.event-feed-analysis-review.v1'){state.review=value.result;}\n if(value.request.action==='deliver'&&value.status==='COMPLETE')state.operation=value.result.operation_id;\n const choices=value.result?.state==='WORKBOOK_COLUMN_CHOICES_REQUIRED';$('column-choice').hidden=!choices;\n if(choices)$('column-proposal').textContent=JSON.stringify(value.result,null,2);\n if(value.progress)$('action-state').textContent+=' · '+JSON.stringify(value.progress);\n controls();\n}\nasync function openAction(id){\n const value=await api(root+'/actions/'+id);await openProgramme(value.programme);\n state.operation=value.request.operation_id;showAction(value);await refreshProgramme();\n if(value.request.note)$('note').value=value.request.note;\n if(value.request.columns)$('columns').value=JSON.stringify(value.request.columns,null,2);\n schedule();\n}\nfunction schedule(){\n clearTimeout(state.poll);\n if(state.action?.status==='RUNNING'){const id=state.action.id,generation=state.generation;state.poll=setTimeout(async()=>{\n  if(state.busy){schedule();return;}\n  try{const value=await api(root+'/actions/'+id);if(generation!==state.generation||state.action?.id!==id)return;showAction(value);if(value.status!=='RUNNING'){await refreshProgramme();await refresh();message(value.status==='COMPLETE'?'The saved action is complete. Review its retained result.':value.error||'Continue the original saved action.',value.status!=='COMPLETE');}schedule();}catch(error){message(error.message,true);}\n },1200);}\n}\n$('open-programme').addEventListener('click',()=>act(()=>openProgramme(selectedName())));\n$('programmes').addEventListener('change',()=>{if($('programmes').value)act(()=>openProgramme($('programmes').value));else{$('programme').value='';++state.generation;state.programme=null;clearSelectedAction();state.fields=[];fieldRows();}});\n$('receive').addEventListener('click',()=>act(upload));\n$('new-input').addEventListener('click',()=>{clearCatalogue();state.input=null;$('input-metadata').textContent='';$('input-status').textContent='Choose another complete original source pair.';try{localStorage.removeItem('sf-event-input:'+state.workspace);}catch{}controls();});\n$('open-input').addEventListener('click',()=>act(async()=>{if(!$('inputs').value)throw Error('Choose a retained source pair.');renderInput(await api(root+'/inputs/'+$('inputs').value));}));\n$('add-field').addEventListener('click',()=>{if(state.fields.length>=100)return;state.fields.push({name:'field_'+(state.fields.length+1),pointer:''});fieldRows();remember();});\n$('use-accepted').addEventListener('click',()=>{state.fields=state.programme.programme.accepted.mapping.fields.map(x=>({...x}));fieldRows();remember();});\n$('review').addEventListener('click',()=>act(()=>submit('review',{input_id:state.input.id,mapping:{fields:state.fields.map(x=>({...x}))}})));\n$('apply').addEventListener('click',()=>act(()=>submit('apply',{review_sha256:state.review.review_sha256,note:$('note').value,columns:JSON.parse($('columns').value)})));\n$('refresh-review').addEventListener('click',()=>act(()=>submit('refresh-review',{review_sha256:state.review.review_sha256,note:$('note').value})));\n$('deliver').addEventListener('click',()=>act(()=>submit('deliver')));\n$('resume').addEventListener('click',()=>act(async()=>{const original=state.action;const value=await api(root+'/named/'+encodeURIComponent(original.programme)+'/actions',{id:original.id,...original.request,resume:true});showAction(value);schedule();}));\n$('refresh').addEventListener('click',()=>act(async()=>{if(state.action)showAction(await api(root+'/actions/'+state.action.id));await refresh();await refreshProgramme();schedule();}));\nfor(const id of ['note','columns'])$(id).addEventListener('input',remember);\nfor(const kind of ['actions','inputs']){$('older-'+kind).addEventListener('click',()=>act(async()=>{state[kind+'Before']=state.overview['next_'+kind];await refresh();}));$('latest-'+kind).addEventListener('click',()=>act(async()=>{state[kind+'Before']=null;await refresh();}));}\nact(async()=>{if(!capability)throw Error('Open this page from the private Analysis launch link.');await refresh();let remembered;try{remembered=JSON.parse(localStorage.getItem('sf-event-input:'+state.workspace));}catch{}if(remembered){try{renderInput(await api(root+'/inputs/'+remembered.id));}catch{}}let previous;try{previous=JSON.parse(localStorage.getItem('sf-event-action:'+state.workspace));}catch{}if(previous){try{await openAction(previous.id);}catch{await openProgramme(previous.programme);state.operation=previous.request.operation_id;showAction({...previous,status:'INTERRUPTED',error:'Reopen or continue the original retained request.'});}}message('Customer workspace ready. Open a programme or receive a complete original file pair.');});\n})();\n"
